-- BP26-PRIVACY-1 (2026-10-26, charter pillar security; owner directive 2026-10-26 "Implement general best practices systemwide across the fleet"; agent_issues 1000342 BP26-GDPR-RECORDS-1,
-- 1000343 BP26-DPIA-1, 1000344 BP26-RETENTION-1, 1000346 BP26-AI-ACT-ARTICLE4-1; breach bp26_metrics_unmeasured, trigger 14541, agent_issues 1000363).
-- WHAT WAS WRONG: the five privacy metrics read UNMEASURED because nothing registered what the fleet keeps, for how long, or whether it is kept longer. records_past_retention names a "retention_policy
-- registry, to build"; ropa_last_reviewed_days, dpia_current, subscribers_with_consent_proof and pii_in_logs take their input from the repository, a GitHub read, two databases and the Workers Logs API.
-- WHAT THIS DOES (three parts, all report-only):
--   1. retention_policy: the registry (policy_key, database, table, the columns a sweep would blank, retention_days, personal_data, basis, the read-only SELECT COUNT(*) that counts rows past the period
--      that still hold the data, measured_by, enforcement, policy_status, last count). 19 policies seeded from tables that really exist: 13 in qnfo-audit (mail bodies, raw messages, drafts, loop
--      quarantine, owner commands, parse failures, unconfirmed and unsubscribed subscribers, correspondents, tool-call logs, calendar deliveries, strategic-mail handoffs, mail metadata) and 6 in other
--      databases (ipatent-db sessions, analytics and submissions; q08-signal pending subscribers; living-paper email_logs). Every period is a PROPOSAL (policy_status proposed): message bodies at 30 days is the
--      figure of BP26-RETENTION-1; the rest are drafts for the owner to adopt or change in docs/RETENTION.md.
--   2. records_past_retention: ONE trigger on fleet_tick_heavy (never fleet_tick), each statement gated on its own row being 50 minutes old, plus the same statements once at apply, exactly the pattern of
--      migrations/2026-10-27-bp26-sql-producers.sql. The 13 qnfo-audit policies are counted here; the 6 other-database policies are counted by scripts/bp26_privacy.py collect_retention_other_dbs, which
--      writes their rows in this table, and the metric is the sum of every counted policy. A policy never counted adds nothing (unknown is never a value); retention_policy.checked_at says which were.
--   3. the owner card bp26-retention-enforce (IDENTITY-BOUND) and the metric sources of the other four metrics.
-- MEASURED 2026-10-26T18:3xZ against live qnfo-audit before this file was written (read-only aggregates, no address read): emails 944 rows, 683 older than 30 days and still holding body_text or body_html
-- (oldest 2026-08-03); email_raw_archive 205 rows, 5 older than 30 days; email_loop_quarantine 105 older than 30 days with a body; email_reply_queue drafts, email_commands, email_parse_failures, mcp_log
-- (4794 rows, oldest 2026-08-28), email_calendar_delivery, handoffs and contact_ledger (242 rows): none past their period; subscribers 3 pending (none older than 30 days) and 1 subscribed with confirmed_at;
-- q08-signal.subscribers 0 rows; living-paper.email_logs 0 rows; ipatent-db sessions 11, analytics 41 and submissions 68 (41 older than 90 days) with raw IP addresses (longest value 36 characters).
-- Expected first value of records_past_retention: 793 (683 + 5 + 105) from this file, 886 once the runner has counted the ipatent-db rows (11 + 41 + 41).
-- NOT BUILT HERE, and why: any purge. Blanking mail bodies, deleting raw messages or subscriber rows is irreversible and concerns the personal data of the owner's correspondents and of the owner, so it is the
-- owner's decision (card bp26-retention-enforce, IDENTITY-BOUND). The metric stays above 0 as an honest breach until that decision; the sweep itself is a code task for after it (qnfo-email and
-- qnfo-subscribers each own their tables; a TTL sweep on fleet cron that reads retention_policy where enforcement = 'enforce' and ops_config retention_enforce = 'on'). No sweep exists today: git grep on main
-- 2026-10-26 finds no DELETE FROM on emails, email_raw_archive, email_loop_quarantine, email_reply_queue, email_commands, mcp_log, handoffs or subscribers in any worker or script (the only hits are guard test data).
-- Revert: the Rollback line drops the trigger and the table, puts the five metrics back to UNMEASURED and removes the card.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DROP TRIGGER IF EXISTS bp26_retention_heavy_tick; UPDATE metric_registry SET last_value = NULL, last_refreshed = NULL, state = 'UNMEASURED', refresh_class = NULL, source_of_truth = CASE metric WHEN 'records_past_retention' THEN 'retention registry (to build) [BP26]' WHEN 'ropa_last_reviewed_days' THEN 'repository (to compute) [BP26]' WHEN 'dpia_current' THEN 'repository docs/dpia/ (to compute) [BP26]' WHEN 'subscribers_with_consent_proof' THEN 'subscriber tables (to compute) [BP26]' ELSE 'log sample scan (to build) [BP26]' END WHERE metric IN ('records_past_retention', 'ropa_last_reviewed_days', 'dpia_current', 'subscribers_with_consent_proof', 'pii_in_logs'); DROP TABLE IF EXISTS retention_policy; DELETE FROM human_actions WHERE slug = 'bp26-retention-enforce';
-- spof-review: fleet_tick_heavy has one producer until FLEET-TICK-HEAVY-SECOND-PRODUCER-1 lands; a missed heavy tick only delays records_past_retention, and metric_staleness_breach_rec records the gap. Each statement reads one table once; the registry adds no view.

CREATE TABLE IF NOT EXISTS retention_policy (
  policy_key TEXT PRIMARY KEY,
  db TEXT NOT NULL,
  table_name TEXT NOT NULL,
  column_scope TEXT NOT NULL,
  retention_days INTEGER NOT NULL,
  personal_data INTEGER NOT NULL DEFAULT 1,
  basis TEXT,
  past_sql TEXT NOT NULL,
  measured_by TEXT NOT NULL CHECK (measured_by IN ('d1-trigger', 'runner')),
  enforcement TEXT NOT NULL DEFAULT 'report' CHECK (enforcement IN ('report', 'enforce')),
  policy_status TEXT NOT NULL DEFAULT 'proposed' CHECK (policy_status IN ('proposed', 'adopted')),
  past_retention INTEGER,
  checked_at TEXT,
  note TEXT,
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

INSERT OR IGNORE INTO retention_policy (policy_key, db, table_name, column_scope, retention_days, personal_data, basis, past_sql, measured_by, enforcement, policy_status) VALUES
  ('emails_bodies_30d', 'qnfo-audit', 'emails', 'body_text, body_html, headers_json', 30, 1, 'GDPR Art. 5(1)(c) and (e); BP26-RETENTION-1 sets message bodies at 30 days; metadata and summaries are kept longer only where needed (emails_metadata_365d)', 'SELECT COUNT(*) FROM emails WHERE substr(received_at,1,10) < date(''now'',''-30 days'') AND (COALESCE(body_text,'''') <> '''' OR COALESCE(body_html,'''') <> '''')', 'd1-trigger', 'report', 'proposed'),
  ('email_raw_archive_30d', 'qnfo-audit', 'email_raw_archive', 'raw_text', 30, 1, 'GDPR Art. 5(1)(c) and (e): the raw message holds everything the parsed body does plus every header and attachment', 'SELECT COUNT(*) FROM email_raw_archive WHERE substr(created_at,1,10) < date(''now'',''-30 days'') AND COALESCE(raw_text,'''') <> ''''', 'd1-trigger', 'report', 'proposed'),
  ('email_reply_queue_drafts_90d', 'qnfo-audit', 'email_reply_queue', 'draft_text, draft_proposed', 90, 1, 'GDPR Art. 5(1)(e): a draft quotes the sender and answers in the owner''s name; the decision row and sender address stay for the audit trail', 'SELECT COUNT(*) FROM email_reply_queue WHERE substr(created_at,1,10) < date(''now'',''-90 days'') AND (COALESCE(draft_text,'''') <> '''' OR COALESCE(draft_proposed,'''') <> '''')', 'd1-trigger', 'report', 'proposed'),
  ('email_loop_quarantine_30d', 'qnfo-audit', 'email_loop_quarantine', 'body_text', 30, 1, 'GDPR Art. 5(1)(e): a quarantined message is a copy of an inbound body kept only to explain why it was not processed', 'SELECT COUNT(*) FROM email_loop_quarantine WHERE substr(COALESCE(quarantined_at, received_at),1,10) < date(''now'',''-30 days'') AND COALESCE(body_text,'''') <> ''''', 'd1-trigger', 'report', 'proposed'),
  ('email_commands_180d', 'qnfo-audit', 'email_commands', 'command_text, result', 180, 1, 'GDPR Art. 5(1)(e): the owner''s own e-mail commands; kept long enough to audit what the fleet did on them', 'SELECT COUNT(*) FROM email_commands WHERE substr(created_at,1,10) < date(''now'',''-180 days'') AND COALESCE(command_text,'''') <> ''''', 'd1-trigger', 'report', 'proposed'),
  ('email_parse_failures_90d', 'qnfo-audit', 'email_parse_failures', 'content_hint, sender, subject', 90, 1, 'GDPR Art. 5(1)(e): a parse failure keeps a content hint of the message that failed; the issue it raised carries the fix', 'SELECT COUNT(*) FROM email_parse_failures WHERE substr(created_at,1,10) < date(''now'',''-90 days'') AND COALESCE(content_hint,'''') <> ''''', 'd1-trigger', 'report', 'proposed'),
  ('subscribers_pending_30d', 'qnfo-audit', 'subscribers', 'row (email, ip_hash, user_agent)', 30, 1, 'GDPR Art. 5(1)(e) and Art. 7: an address whose double opt-in was never completed has no consent; 30 days is longer than the confirmation link is useful', 'SELECT COUNT(*) FROM subscribers WHERE status = ''pending'' AND substr(created_at,1,10) < date(''now'',''-30 days'')', 'd1-trigger', 'report', 'proposed'),
  ('subscribers_unsubscribed_30d', 'qnfo-audit', 'subscribers', 'row (email, ip_hash, user_agent, unsub_token)', 30, 1, 'GDPR Art. 5(1)(e) and Art. 17: after an opt-out the minimal record that proves it is email_suppression; the subscriber row can go', 'SELECT COUNT(*) FROM subscribers WHERE status = ''unsubscribed'' AND substr(COALESCE(updated_at, created_at),1,10) < date(''now'',''-30 days'')', 'd1-trigger', 'report', 'proposed'),
  ('contact_ledger_1095d', 'qnfo-audit', 'contact_ledger', 'row (email, name, affiliation)', 1095, 1, 'GDPR Art. 5(1)(e): a correspondent record with no contact for three years; suppressed rows are kept (suppress = 1) because they prevent a second approach', 'SELECT COUNT(*) FROM contact_ledger WHERE COALESCE(suppress,0) = 0 AND substr(COALESCE(last_contact, first_contact, ''''),1,10) <> '''' AND substr(COALESCE(last_contact, first_contact),1,10) < date(''now'',''-1095 days'')', 'd1-trigger', 'report', 'proposed'),
  ('mcp_log_90d', 'qnfo-audit', 'mcp_log', 'args, result', 90, 1, 'GDPR Art. 5(1)(c) and (e): tool arguments and results can hold addresses and message text (a send logs its recipient)', 'SELECT COUNT(*) FROM mcp_log WHERE substr(ts,1,10) < date(''now'',''-90 days'') AND (COALESCE(args,'''') <> '''' OR COALESCE(result,'''') <> '''')', 'd1-trigger', 'report', 'proposed'),
  ('email_calendar_delivery_90d', 'qnfo-audit', 'email_calendar_delivery', 'row (recipient)', 90, 1, 'GDPR Art. 5(1)(e): a finished reminder or acknowledgement of a calendar invite', 'SELECT COUNT(*) FROM email_calendar_delivery WHERE status IN (''sent'',''skipped'',''superseded'') AND substr(due_at,1,10) < date(''now'',''-90 days'')', 'd1-trigger', 'report', 'proposed'),
  ('handoffs_email_180d', 'qnfo-audit', 'handoffs', 'summary, pending_work, next_action', 180, 1, 'GDPR Art. 5(1)(e): a strategic-mail handoff summarises a sender and a snippet of what they wrote', 'SELECT COUNT(*) FROM handoffs WHERE session_id LIKE ''email-%'' AND substr(timestamp,1,10) < date(''now'',''-180 days'') AND COALESCE(summary,'''') <> ''''', 'd1-trigger', 'report', 'proposed'),
  ('emails_metadata_365d', 'qnfo-audit', 'emails', 'row (sender, recipient, subject)', 365, 1, 'GDPR Art. 5(1)(e): who wrote when and about what, kept a year for the reply and audit trail and no longer', 'SELECT COUNT(*) FROM emails WHERE substr(received_at,1,10) < date(''now'',''-365 days'')', 'd1-trigger', 'report', 'proposed'),
  ('ipatent_sessions_90d', 'ipatent-db', 'sessions', 'row (ip_address, user_agent, country)', 90, 1, 'GDPR Art. 5(1)(c) and (e): a visit session holds a raw IP address and a user agent; the page_views and usage_counts counters keep what is needed', 'SELECT COUNT(*) FROM sessions WHERE substr(first_seen,1,10) < date(''now'',''-90 days'')', 'runner', 'report', 'proposed'),
  ('ipatent_analytics_90d', 'ipatent-db', 'analytics', 'row (ip_address, user_agent, referrer)', 90, 1, 'GDPR Art. 5(1)(c) and (e): per-event analytics with a raw IP address', 'SELECT COUNT(*) FROM analytics WHERE substr(created_at,1,10) < date(''now'',''-90 days'')', 'runner', 'report', 'proposed'),
  ('ipatent_submission_ip_90d', 'ipatent-db', 'submissions', 'ip_address, user_agent', 90, 1, 'GDPR Art. 5(1)(c) and (e): the network address and browser of a submitter are not needed after the draft is delivered', 'SELECT COUNT(*) FROM submissions WHERE substr(created_at,1,10) < date(''now'',''-90 days'') AND (COALESCE(ip_address,'''') <> '''' OR COALESCE(user_agent,'''') <> '''')', 'runner', 'report', 'proposed'),
  ('ipatent_submissions_730d', 'ipatent-db', 'submissions', 'row (inventor_name, inventor_email, disclosure_text)', 730, 1, 'GDPR Art. 5(1)(e): an invention disclosure and its submitter, two years after it was written unless the submitter asks to keep it', 'SELECT COUNT(*) FROM submissions WHERE substr(created_at,1,10) < date(''now'',''-730 days'')', 'runner', 'report', 'proposed'),
  ('q08_subscribers_pending_30d', 'q08-signal', 'subscribers', 'row (email)', 30, 1, 'GDPR Art. 5(1)(e) and Art. 7: an unconfirmed double opt-in on the q08 list', 'SELECT COUNT(*) FROM subscribers WHERE status = ''pending'' AND substr(created_at,1,10) < date(''now'',''-30 days'')', 'runner', 'report', 'proposed'),
  ('living_paper_email_logs_30d', 'living-paper', 'email_logs', 'from_addr, subject, body', 30, 1, 'GDPR Art. 5(1)(c) and (e): a mail log with sender, subject and body; the table is empty today and the policy keeps it so', 'SELECT COUNT(*) FROM email_logs WHERE substr(ts,1,10) < date(''now'',''-30 days'')', 'runner', 'report', 'proposed');

UPDATE metric_registry SET source_of_truth = 'GitHub commits API on docs/ROPA.md (scripts/bp26_privacy.py collect_review_docs, hourly from the remediation-consumer runner): days since the file''s last commit on main; it measures that the record is kept and reviewed, not that it is adequate [BP26]' WHERE metric = 'ropa_last_reviewed_days' AND instr(source_of_truth, '[BP26]') > 0;
UPDATE metric_registry SET source_of_truth = 'GitHub commits API on docs/dpia/email-agent.md, personal-twin.md and ipatent.md (scripts/bp26_privacy.py collect_review_docs, hourly): files changed in the last 365 days / 3; it measures existence and recency of the review file, not its adequacy [BP26]' WHERE metric = 'dpia_current' AND instr(source_of_truth, '[BP26]') > 0;
UPDATE metric_registry SET source_of_truth = 'qnfo-audit.subscribers (status subscribed, confirmed_at) and q08-signal.subscribers (status confirmed, confirmed_at), aggregates only (scripts/bp26_privacy.py collect_consent_proof, hourly); the companion list lives in the personal plane and is not read here [BP26]' WHERE metric = 'subscribers_with_consent_proof' AND instr(source_of_truth, '[BP26]') > 0;
UPDATE metric_registry SET source_of_truth = 'qnfo-audit.retention_policy: rows past each registered period that still hold the data; qnfo-audit tables by trigger bp26_retention_heavy_tick on fleet_tick_heavy, other databases by scripts/bp26_privacy.py collect_retention_other_dbs; counted only, nothing is purged (owner card bp26-retention-enforce) [BP26]' WHERE metric = 'records_past_retention' AND instr(source_of_truth, '[BP26]') > 0;
UPDATE metric_registry SET source_of_truth = 'Workers Observability telemetry API, 8 three-hour windows of the last 24 h, newest 250 events each (scripts/bp26_privacy.py collect_pii_in_logs, every 6 h): raw e-mail address matches, counted per worker, never stored [BP26]' WHERE metric = 'pii_in_logs' AND instr(source_of_truth, '[BP26]') > 0;

-- First measurement at apply (the same statements the trigger runs, without the 50-minute gate).
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM emails WHERE substr(received_at,1,10) < date('now','-30 days') AND (COALESCE(body_text,'') <> '' OR COALESCE(body_html,'') <> '')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'emails_bodies_30d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_raw_archive WHERE substr(created_at,1,10) < date('now','-30 days') AND COALESCE(raw_text,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'email_raw_archive_30d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_reply_queue WHERE substr(created_at,1,10) < date('now','-90 days') AND (COALESCE(draft_text,'') <> '' OR COALESCE(draft_proposed,'') <> '')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'email_reply_queue_drafts_90d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_loop_quarantine WHERE substr(COALESCE(quarantined_at, received_at),1,10) < date('now','-30 days') AND COALESCE(body_text,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'email_loop_quarantine_30d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_commands WHERE substr(created_at,1,10) < date('now','-180 days') AND COALESCE(command_text,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'email_commands_180d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_parse_failures WHERE substr(created_at,1,10) < date('now','-90 days') AND COALESCE(content_hint,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'email_parse_failures_90d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM subscribers WHERE status = 'pending' AND substr(created_at,1,10) < date('now','-30 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'subscribers_pending_30d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM subscribers WHERE status = 'unsubscribed' AND substr(COALESCE(updated_at, created_at),1,10) < date('now','-30 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'subscribers_unsubscribed_30d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM contact_ledger WHERE COALESCE(suppress,0) = 0 AND substr(COALESCE(last_contact, first_contact, ''),1,10) <> '' AND substr(COALESCE(last_contact, first_contact),1,10) < date('now','-1095 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'contact_ledger_1095d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM mcp_log WHERE substr(ts,1,10) < date('now','-90 days') AND (COALESCE(args,'') <> '' OR COALESCE(result,'') <> '')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'mcp_log_90d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_calendar_delivery WHERE status IN ('sent','skipped','superseded') AND substr(due_at,1,10) < date('now','-90 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'email_calendar_delivery_90d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM handoffs WHERE session_id LIKE 'email-%' AND substr(timestamp,1,10) < date('now','-180 days') AND COALESCE(summary,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'handoffs_email_180d';
UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM emails WHERE substr(received_at,1,10) < date('now','-365 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE policy_key = 'emails_metadata_365d';

UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', refresh_class = 'd1-trigger',
    last_value = CAST((SELECT COALESCE(SUM(past_retention), 0) FROM retention_policy WHERE past_retention IS NOT NULL) AS TEXT)
  WHERE metric = 'records_past_retention' AND instr(source_of_truth, '[BP26]') > 0 AND NOT EXISTS (SELECT 1 FROM retention_policy WHERE measured_by = 'd1-trigger' AND checked_at IS NULL);

-- Hourly refresh on the heavy heartbeat (one trigger, one gated statement per qnfo-audit policy, then the metric).
CREATE TRIGGER IF NOT EXISTS bp26_retention_heavy_tick AFTER INSERT ON fleet_tick_heavy
BEGIN
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM emails WHERE substr(received_at,1,10) < date('now','-30 days') AND (COALESCE(body_text,'') <> '' OR COALESCE(body_html,'') <> '')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'emails_bodies_30d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_raw_archive WHERE substr(created_at,1,10) < date('now','-30 days') AND COALESCE(raw_text,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'email_raw_archive_30d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_reply_queue WHERE substr(created_at,1,10) < date('now','-90 days') AND (COALESCE(draft_text,'') <> '' OR COALESCE(draft_proposed,'') <> '')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'email_reply_queue_drafts_90d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_loop_quarantine WHERE substr(COALESCE(quarantined_at, received_at),1,10) < date('now','-30 days') AND COALESCE(body_text,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'email_loop_quarantine_30d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_commands WHERE substr(created_at,1,10) < date('now','-180 days') AND COALESCE(command_text,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'email_commands_180d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_parse_failures WHERE substr(created_at,1,10) < date('now','-90 days') AND COALESCE(content_hint,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'email_parse_failures_90d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM subscribers WHERE status = 'pending' AND substr(created_at,1,10) < date('now','-30 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'subscribers_pending_30d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM subscribers WHERE status = 'unsubscribed' AND substr(COALESCE(updated_at, created_at),1,10) < date('now','-30 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'subscribers_unsubscribed_30d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM contact_ledger WHERE COALESCE(suppress,0) = 0 AND substr(COALESCE(last_contact, first_contact, ''),1,10) <> '' AND substr(COALESCE(last_contact, first_contact),1,10) < date('now','-1095 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'contact_ledger_1095d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM mcp_log WHERE substr(ts,1,10) < date('now','-90 days') AND (COALESCE(args,'') <> '' OR COALESCE(result,'') <> '')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'mcp_log_90d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM email_calendar_delivery WHERE status IN ('sent','skipped','superseded') AND substr(due_at,1,10) < date('now','-90 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'email_calendar_delivery_90d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM handoffs WHERE session_id LIKE 'email-%' AND substr(timestamp,1,10) < date('now','-180 days') AND COALESCE(summary,'') <> ''), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'handoffs_email_180d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE retention_policy SET past_retention = (SELECT COUNT(*) FROM emails WHERE substr(received_at,1,10) < date('now','-365 days')), checked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE policy_key = 'emails_metadata_365d' AND measured_by = 'd1-trigger' AND (checked_at IS NULL OR checked_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes'));
  UPDATE metric_registry SET last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), state = 'MEASURED', refresh_class = 'd1-trigger',
      last_value = CAST((SELECT COALESCE(SUM(past_retention), 0) FROM retention_policy WHERE past_retention IS NOT NULL) AS TEXT)
    WHERE metric = 'records_past_retention' AND instr(source_of_truth, '[BP26]') > 0 AND (last_refreshed IS NULL OR last_refreshed < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-50 minutes')) AND NOT EXISTS (SELECT 1 FROM retention_policy WHERE measured_by = 'd1-trigger' AND checked_at IS NULL);
END;

INSERT OR IGNORE INTO human_actions (slug, title, why, default_in_effect, action, sev, status, source) VALUES ('bp26-retention-enforce',
  'Decide whether the fleet starts deleting mail-derived personal data once it is past its retention period (message bodies: 30 days)',
  'IDENTITY-BOUND: deleting or blanking mail bodies, raw messages, drafts and subscriber rows is irreversible and they hold the personal data of your correspondents and of you, so the fleet will not start it on its own. It now counts what is past the proposed periods (retention_policy; records_past_retention was 793 qnfo-audit rows on 2026-10-26: 683 message bodies older than 30 days, 5 raw messages, 105 loop-quarantine bodies, plus 93 ipatent-db rows past 90 days). The periods in docs/RETENTION.md are proposals (message bodies at 30 days is the BP26-RETENTION-1 figure); the periods the law requires of you are for you, and your data-protection adviser if you have one, to set. Nothing in the repository is legal advice.',
  'Report-only: nothing is deleted, retention_policy keeps counting, and records_past_retention stays above 0 as an honest breach. The sweep is built after your answer, not before.',
  'Reply ''enforce'' to have the sweep built and turned on (it resolves when ops_config key retention_enforce is on: SELECT value FROM ops_config WHERE key = ''retention_enforce''), ''adjust <policy_key> <days>'' to change a period first, or ''keep'' to leave the data as it is.',
  'normal', 'open', 'bp26-privacy');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-rem-a8-privacy',
  'a retention period is the owner''s decision and a purge of mail-derived personal data is irreversible, so the fleet registers and counts what is past each proposed period and asks before it deletes anything; unknown stays unknown and a policy never counted adds nothing to the metric',
  'BP26-PRIVACY-1: retention_policy registry (19 policies), trigger bp26_retention_heavy_tick on fleet_tick_heavy for the qnfo-audit policies, sources of five privacy metrics, owner card bp26-retention-enforce; no purge',
  'qnfo-audit 2026-10-26T18:3xZ read-only: emails 944 rows of which 683 older than 30 days still hold a body; email_raw_archive 5 older than 30 days; email_loop_quarantine 105; ipatent-db sessions 11, analytics 41, submissions 41 older than 90 days with raw IP addresses; git grep on origin/main finds no sweep of any of them',
  'applied by migration; records_past_retention reads 793 at apply and 886 after the first runner count',
  'one new table, one new trigger on fleet_tick_heavy, five metric_registry source texts, one human_actions card; nothing is deleted',
  'the Rollback line', 'the fleet can say, per table, how much personal data it holds past a period and which period is only a proposal',
  'records_past_retention stays above 0 until the owner answers the card; ropa_last_reviewed_days, dpia_current and subscribers_with_consent_proof are measured by the next remediation-consumer run after merge',
  'none directly; it makes the GDPR Art. 5(1)(e) storage-limitation gap visible', 'offline: migrations/bp26-privacy.test.mjs on node:sqlite; live: qnfo-audit reads before writing the file'
WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.action LIKE 'BP26-PRIVACY-1:%');
